INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (33, 440, 'Type 1300 OPP tape slitting machine', '../', '<p>Type 1300 OPP tape slitting machine<br/> <br/> Scope of application: applicable to OPP sealing tape / stationery tape Characteristic.<br/> 1 for this machine are: centralized control panel control, simple operation.<br/> Type length 2 three set: three segment length counting and advanced, ensure accurate rewinding length.<br/> 3: automatic exchange shaft coiling operation is completed, the two automatic switching, simple operation, high efficiency.<br/> 4the arch expansion wheel: wheel design unique arch. Carefully remove out the wrinkling of adhesive tape in the process of feeding<br/> 5pneumatic braking: when the machine is stopped, the tape could stop the instant, accurate positioning, accurate label<br/> <br/> Technical parameters:<br/> The effective width of 1300mm 1000mm<br/> The maximum volume value diameter Phi 120mm Phi 120mm Maximum roll diameter Phi 600mm Phi 600mm<br/> The minimum strip width 12mm 12mm<br/> Paper tube diameter phi 76.2mm phi 25.4-76.2mm The mechanical speed of 0-180M/min 0-180M/min The main motor 5HP 5HP<br/> &nbsp;<br/> 2023 new slitting machine cutting tube machine Cutting tube machine<br/> Applicable to the cutting of paper tube. Technical parameters<br/> The effective width of 500mm The minimum width of cut 12mm Paper tube diameter 76.2mm Paper tube thickness 3-5mm Pressure 5kg\cmcm<br/> &nbsp;<br/> 200 small winder<br/> 1this machine is suitable for bad tape products re winder, to ensure the quality of batch products, consistency and reduce waste<br/> 2winding shaft using DC motor drive, can be stepless variable speed<br/> The 3 meter long operation panel device, convenient volume set length<br/> Application: used for rewinding of defective products Special<br/> Electronic digital display type tension control, convenient operation Variable frequency speed regulation, start running smoothly, no noise<br/> Length is controlled by a length function, which is more stable and accurate stop<br/> Structure is simplified. The operation speed is quick, the characteristics of higher productivity<br/> <p>Wearing the machine</p> <p><br/></p>', '2026-09-06 20:58:45');
