INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (33, 403, 'BOPP Metallized film aluminium silver', '../upload/image/20211215/20211215203711_18066.jpg', '<p><span class="nownavi" style="font-family:Tahoma;"><strong><span class="nownavi"><span style="font-size:18px;color:#009900;">BOPP Metallized film aluminium silver</span><br/> </span></strong></span></p> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <strong><span style="font-size:18px;color:#009900;font-family:Tahoma;">BOPP (</span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;">Polypropylene)</span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;">aluminum&nbsp;</span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;">metallized film (silver)</span> </strong> </div> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <strong><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Thickness : 15,18,20,25,30,35 Microns</strong></span><br/> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Width : 350-1500MM</strong></span><br/> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Length :5000-12000M</strong></span><strong>&nbsp;</strong><br/> <div> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Color : silver&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>aluminum&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>metallized</strong></span> </div> <div> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Package : Standard exporting package with pallets .</strong></span><br/> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Application : lamination &amp; printing and so forth.</strong></span> </div> <div> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Usgae: food packing or others packing.</strong></span> </div> </strong> </div> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <strong><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>Future:&nbsp; inner side corona treatment and&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>aluminum&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>metallized, outer&nbsp;</strong></span><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>side heat sealable, ( basic BOPP is two sides heat sealable BOPP）</strong></span> </strong> </div> <strong> <p></p> <div style="font-family:Calibri;font-size:19px;background-color:#FFFFFF;"> <span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>or&nbsp;</strong></span><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>outer side corona treatment and&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>aluminum&nbsp;</strong></span><span style="background-color:transparent;font-size:18px;color:#009900;font-family:Tahoma;"><strong>metallized, and inner&nbsp;</strong></span><span style="font-size:18px;color:#009900;font-family:Tahoma;"><strong>side heat sealable, ( basic BOPP is two sides heat sealable BOPP）</strong></span> </div> </strong> <p><br/></p> <div style="color:#000000;font-family:Calibri;font-size:19px;font-style:normal;font-weight:400;text-align:start;background-color:#FFFFFF;"> <br/> </div> <br/> <p><br/></p> <p><span class="nownavi"><br/> </span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (33, 402, 'thermal transfer ribbons& thermal transfer labels', '../upload/image/20191016/20191016084516_37993.jpg', '<p><span style="color:#009688;font-family:&quot;font-size:14px;background-color:#F2F2F2;">thermal transfer ribbons&amp; thermal transfer labels<br/> Understanding Thermal Transfer Ribbons<br/> <br/> Thermal transfer printer alongside different thermal transfer ribbon choices<br/> If you''re planning to print labels with a thermal transfer printer, you''re going to need thermal transfer ribbons in addition to thermal transfer labels. Here''s everything you need to know about selecting the right thermal transfer ribbon for your printer and project.<br/> <br/> Ribbon Type / Wind Direction<br/> Wind directions of CSO vs CSI thermal transfer ribbons<br/> You may notice when shopping for printer ribbons that there are two categories: coated side out (CSO) and coated side in (CSI). This refers to where the ink coating is placed on the ribbons. It affects how they''re wound and fed through the printer – most printers can only take one style or the other.<br/> <br/> Coated Side Out (CSO) Ribbons<br/> Coated side out ribbons are printing ribbons that have the ink coating facing outside. Zebra&reg; thermal transfer printers typically use this type of ribbon. You''ll notice that the ink is on the outside of the ribbon roll and that it unrolls from the bottom before making contact with the print-head and label.<br/> <br/> To correctly insert this ribbon type into your printer, unroll it from the bottom and feed it underneath.<br/> <br/> Shop CSO Ribbons<br/> Coated Side In (CSI) Ribbons<br/> Coated side in ribbons are printing ribbons that have the ink facing inside. Datamax&reg; and Sato&reg; thermal transfer printers most commonly use CSI ribbons. You''ll notice that the ink is on the inside of the ribbon roll and that it unrolls from the top before making contact with the print-head and label.<br/> <br/> To correctly insert this ribbon type into your printer, unroll it from the top and feed it over.<br/> <br/> Shop CSI Ribbons&nbsp;<br/> You can also determine your ribbon type/wind direction using the tape test: Stick a piece of tape to the outside of your ribbon roll. After a few seconds, peel the tape off. If ink sticks to the tape, you were using a CSO ribbon. If no ink sticks to the tape, you were using a CSI ribbon.<br/> <br/> Ribbon Size<br/> There are a couple of criteria to consider when selecting a thermal transfer ribbon size. They are:<br/> <br/> Label width<br/> Pick the ribbon width closest to that of your most commonly used label. For example, if you''re printing a 2.5 inch wide label, you should purchase a 3.27 inch ribbon as opposed to a 4.33 inch one. Any unused ink on the thermal transfer ribbon will go to waste otherwise. You should also be conscious to buy a width that fits in your printer.<br/> <br/> Ribbon length<br/> Typically, ribbons with a shorter length are intended for desktop thermal transfer printers while the longer lengths are intended for industrial ones. Our ribbons range from 243 feet to 1,476 feet.<br/> <br/> Core size<br/> Smaller printers don''t have as much space to accommodate larger ribbon cores. While a 1 inch core is standard, smaller printers use a 0.5 inch core.<br/> <br/> <br/> Is your label size the best fit for your project? Our selection of thermal transfer roll labels includes more than 75 unique label sizes for both 1 inch and 3 inch core sizes.<br/> <br/> </span></p>', '2026-09-06 20:58:45');
